package com.acxiom.crm.followup;
import com.acxiom.crm.audit.AuditService; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BeanPropertyBindingResult;
import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@Controller public class FollowUpController {
 private final FollowUpRepository repo; private final AuditService audit; private static final List<String> STATUSES=List.of("Planned","Completed","Missed","Cancelled"); private static final List<String> TYPES=List.of("Call","Email","Meeting","Task"); private static final List<String> RELATED=List.of("Customer","Lead","Opportunity");
 public FollowUpController(FollowUpRepository r,AuditService a){repo=r;audit=a;}
 private void data(Model m){m.addAttribute("statuses",STATUSES);m.addAttribute("types",TYPES);m.addAttribute("relatedTypes",RELATED);m.addAttribute("today",LocalDate.now());}
 @GetMapping("/followups") public String list(Model m){var rows=repo.findAll().stream().sorted((a,b)->a.getFollowUpDate().compareTo(b.getFollowUpDate())).toList();m.addAttribute("followups",rows);m.addAttribute("pending",rows.stream().filter(f->"Planned".equals(f.getStatus())).count());m.addAttribute("overdue",rows.stream().filter(FollowUp::isOverdue).count());return "followups";}
 @GetMapping("/followups/new") public String form(Model m){m.addAttribute("followup",new FollowUp());data(m);return "followup-form";}
 @PostMapping("/followups") public String create(@Valid @ModelAttribute("followup") FollowUp f,BindingResult r,Model m){if(f.getFollowUpDate()!=null&&f.getFollowUpDate().isBefore(LocalDate.now())&&"Planned".equals(f.getStatus()))r.rejectValue("followUpDate","past","A planned follow-up cannot be in the past.");if(!RELATED.contains(f.getRelatedType()))r.rejectValue("relatedType","invalid","Select a valid related type.");if(!TYPES.contains(f.getType()))r.rejectValue("type","invalid","Select a valid activity type.");if(!STATUSES.contains(f.getStatus()))r.rejectValue("status","invalid","Select a valid status.");if(r.hasErrors()){data(m);return "followup-form";}repo.save(f);audit.log("FOLLOWUP","CREATE",f.getId(),"Created follow-up: "+f.getSubject());return "redirect:/followups";}
 @GetMapping("/followups/{id}/edit") public String edit(@PathVariable Long id,Model m){m.addAttribute("followup",repo.findById(id).orElseThrow());data(m);return "followup-form";}
 @PostMapping("/followups/{id}") public String update(@PathVariable Long id,@Valid @ModelAttribute("followup") FollowUp f,BindingResult r,Model m){FollowUp old=repo.findById(id).orElseThrow();if(f.getFollowUpDate()!=null&&f.getFollowUpDate().isBefore(LocalDate.now())&&"Planned".equals(f.getStatus()))r.rejectValue("followUpDate","past","A planned follow-up cannot be in the past.");if(!RELATED.contains(f.getRelatedType()))r.rejectValue("relatedType","invalid","Select a valid related type.");if(!TYPES.contains(f.getType()))r.rejectValue("type","invalid","Select a valid activity type.");if(!STATUSES.contains(f.getStatus()))r.rejectValue("status","invalid","Select a valid status.");if(r.hasErrors()){data(m);return "followup-form";}old.setSubject(f.getSubject());old.setFollowUpDate(f.getFollowUpDate());old.setRelatedType(f.getRelatedType());old.setRelatedId(f.getRelatedId());old.setType(f.getType());old.setStatus(f.getStatus());old.setAssignedUser(f.getAssignedUser());old.setNotes(f.getNotes());repo.save(old);audit.log("FOLLOWUP","UPDATE",old.getId(),"Updated follow-up: "+old.getSubject());return "redirect:/followups";}
 @PostMapping("/followups/{id}/delete") public String delete(@PathVariable Long id){repo.deleteById(id);audit.log("FOLLOWUP","DELETE",id,"Deleted follow-up");return "redirect:/followups";}
}
